mapper.select:
select ifnull(sum(d.quantity), 0)
  from wm_product_recpt_detail d
  join wm_product_recpt r on r.recpt_id = d.recpt_id
 where d.area_id = #{areaId}
   and r.status in ('APPROVING', 'APPROVED')
   and d.item_id <> #{itemId}
   and d.detail_id <> #{excludeDetailId}

select ifnull(sum(d.quantity), 0)
  from wm_product_recpt_detail d
  join wm_product_recpt r on r.recpt_id = d.recpt_id
 where d.area_id = #{areaId}
   and r.status in ('APPROVING', 'APPROVED')
   and d.item_id = #{itemId}
   and ifnull(d.batch_code, '') <> ifnull(#{batchCode}, '')
   and d.detail_id <> #{excludeDetailId}

select group_concat(distinct s.item_name separator '、')
  from wm_material_stock s
 where s.area_id = #{areaId}
   and s.item_id <> #{itemId}
   and s.quantity_onhand > 0

select group_concat(distinct ifnull(s.batch_code, '(无批次)') separator '、')
  from wm_material_stock s
 where s.area_id = #{areaId}
   and s.item_id = #{itemId}
   and s.quantity_onhand > 0
   and ifnull(s.batch_code, '') <> ifnull(#{batchCode}, '')

select ifnull(sum(d.quantity), 0)
  from wm_product_recpt_detail d
 where d.line_id = #{lineId}
   and d.detail_id <> #{excludeDetailId}
